/*
 * A100368  Numbers of the form 2^k * p where k > 0 and p is an odd prime.
 * https://oeis.org/A100368
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = the nth smallest integer of the form 2^k * p, where k > 0
 *            and p is an odd prime. The sequence is generated by maintaining
 *            a min‑heap of the next multiple for each odd prime. The
 *            algorithm runs in O(n log π(max)) where π(max) is the number of
 *            primes below the chosen sieve limit
 * Range:     u8 none, u16 none, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* ------------------------------------------------------------ */
/* Prime table (odd primes) up to a fixed sieve limit           */
#define SIEVE_LIMIT 10000000ULL            /* 1e7 – enough for n≈10^4     */
static uint8_t  *is_composite = NULL;     /* sieve flag array            */
static uint32_t *primes      = NULL;       /* list of odd primes          */
static size_t   prime_count  = 0;          /* number of primes generated */

/* ------------------------------------------------------------ */
/* Heap of current candidates */
typedef struct { seq_t val; } HeapNode;
static HeapNode *heap       = NULL;        /* heap array                 */
static size_t   heap_size   = 0;           /* current size               */

/* ------------------------------------------------------------ */
/* Output memoisation */
static seq_t *memo          = NULL;        /* stored sequence values     */
static size_t memo_len      = 0;           /* number of values stored    */
static size_t memo_cap      = 0;           /* capacity of memo array     */

/* ------------------------------------------------------------ */
/* Utility functions for the binary min‑heap */
static inline void sift_up(size_t i)
{
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (heap[p].val <= heap[i].val) break;
        HeapNode tmp = heap[p];
        heap[p] = heap[i];
        heap[i] = tmp;
        i = p;
    }
}

static inline void sift_down(size_t i)
{
    for (;;) {
        size_t l = (i << 1) + 1;
        if (l >= heap_size) break;
        size_t r = l + 1;
        size_t s = (r < heap_size && heap[r].val < heap[l].val) ? r : l;
        if (heap[i].val <= heap[s].val) break;
        HeapNode tmp = heap[i];
        heap[i] = heap[s];
        heap[s] = tmp;
        i = s;
    }
}

/* ------------------------------------------------------------ */
/* Sieve of Eratosthenes producing odd primes up to SIEVE_LIMIT */
static void generate_primes(void)
{
    if (primes != NULL) return;            /* already generated */

    is_composite = (uint8_t *)malloc((SIEVE_LIMIT + 1) * sizeof(uint8_t));
    if (!is_composite) return;
    for (uint64_t i = 0; i <= SIEVE_LIMIT; ++i) is_composite[i] = 0;

    for (uint64_t i = 3; i * i <= SIEVE_LIMIT; i += 2)
        if (!is_composite[i])
            for (uint64_t j = i * i; j <= SIEVE_LIMIT; j += 2 * i)
                is_composite[j] = 1;

    size_t est = SIEVE_LIMIT / 10;
    primes = (uint32_t *)malloc(est * sizeof(uint32_t));
    if (!primes) return;

    prime_count = 0;
    for (uint64_t i = 3; i <= SIEVE_LIMIT; i += 2)
        if (!is_composite[i]) {
            if (prime_count == est) {
                est <<= 1;
                uint32_t *tmp = (uint32_t *)realloc(primes, est * sizeof(uint32_t));
                if (!tmp) return;
                primes = tmp;
            }
            primes[prime_count++] = (uint32_t)i;
        }
}

/* ------------------------------------------------------------ */
/* Initialise heap, memo and prime table on first call */
static void init_once(void)
{
    generate_primes();
    heap_size = prime_count;
    heap = (HeapNode *)malloc(heap_size * sizeof(HeapNode));
    if (!heap) return;
    for (size_t i = 0; i < heap_size; ++i)
        heap[i].val = (seq_t)(2ULL * (uint64_t)primes[i]);

    /* heapify: build min‑heap */
    for (size_t i = (heap_size >> 1); i-- > 0; )
        sift_down(i);

    memo_cap = 1024;
    memo = (seq_t *)malloc(memo_cap * sizeof(seq_t));
    memo_len = 0;
}

/* ------------------------------------------------------------ */
/* Ensure memo array can hold at least n elements */
static void ensure_memo(size_t n)
{
    while (memo_cap < n) {
        memo_cap <<= 1;
        seq_t *tmp = (seq_t *)realloc(memo, memo_cap * sizeof(seq_t));
        if (!tmp) return;
        memo = tmp;
    }
}

/* ------------------------------------------------------------ */
/* Main sequence function */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;           /* offset is 1 – safe guard */

    static bool initialized = false;
    if (!initialized) {
        init_once();
        initialized = true;
    }

    ensure_memo((size_t)n);

    /* Generate terms until we reach n */
    while (memo_len < (size_t)n) {
        /* Smallest candidate is at heap[0] */
        seq_t value = heap[0].val;
        memo[memo_len++] = value;

        /* Double its prime factor: 2^(k+1)*p */
        heap[0].val = heap[0].val * (seq_t)2;
        sift_down(0);
    }

    return memo[(size_t)n - 1];
}
